/** Object-model action validation shared by REPL sessions and adapters. */
import { ActionError } from './errors.js';
import { z } from 'zod';
import type { Expectation } from '../shared/page-contract.js';
import type { ActAction, Target } from './tab.js';

export interface RawTarget {
  ref?: string | number;
  selector?: string;
  within?: string;
  nth?: number;
  role?: string;
  name?: string;
  label?: string;
  text?: string;
  testid?: string;
  x?: number;
  y?: number;
  frame?: Target['frame'];
}

export interface ActToolInput {
  action: ActAction;
  target?: RawTarget;
  to?: RawTarget;
  value?: string;
  files?: string[];
  direction?: 'up' | 'down' | 'left' | 'right';
  amount?: number;
  method?: 'cdp' | 'dom';
  timeoutMs?: number;
  settleMs?: number;
}

const frame = z.union([z.string(), z.number().int()]);
const targetShape = z.object({
  ref: z.union([z.string(), z.number().int()]).optional(),
  selector: z.string().optional(), within: z.string().optional(), nth: z.number().int().optional(),
  role: z.string().optional(), name: z.string().optional(), label: z.string().optional(), text: z.string().optional(), testid: z.string().optional(),
  x: z.number().optional(), y: z.number().optional(), frame: z.union([frame, z.array(frame)]).optional(),
}).strict();
const actionShape = z.object({
  action: z.string(), target: targetShape.optional(), to: targetShape.optional(), value: z.string().optional(),
  files: z.array(z.string().min(1)).optional(), direction: z.enum(['up', 'down', 'left', 'right']).optional(), amount: z.number().optional(),
  timeoutMs: z.number().int().nonnegative().optional(), settleMs: z.number().int().min(0).max(10_000).optional(), method: z.enum(['cdp', 'dom']).optional(),
}).strict();
const expectationShape = z.object({ target: targetShape.optional(), text: z.string().min(1).optional(), notText: z.string().min(1).optional(), url: z.string().min(1).optional(), title: z.string().min(1).optional(), visible: z.boolean().optional(), value: z.string().optional(), checked: z.boolean().optional(), selected: z.array(z.string()).optional(), enabled: z.boolean().optional() }).strict();

function validate(shape: z.ZodType, value: unknown): void {
  const result = shape.safeParse(value);
  if (!result.success) throw new ActionError('invalid_args', result.error.issues.map(i => `${i.path.join('.') || 'input'}: ${i.message}`).join('; '), 'Read docs_get with name:"api-reference" and member:"Tab.act" or "Tab.expect" for exact fields.');
}

type Need = 'required' | 'nonempty' | 'present' | 'optional' | 'forbidden';

export const ACTION_RULES: Record<ActAction, { target: Need; value: Need; files: Need; to: Need; scroll: boolean }> = {
  click: { target: 'required', value: 'forbidden', files: 'forbidden', to: 'forbidden', scroll: false },
  dblclick: { target: 'required', value: 'forbidden', files: 'forbidden', to: 'forbidden', scroll: false },
  hover: { target: 'required', value: 'forbidden', files: 'forbidden', to: 'forbidden', scroll: false },
  focus: { target: 'required', value: 'forbidden', files: 'forbidden', to: 'forbidden', scroll: false },
  check: { target: 'required', value: 'forbidden', files: 'forbidden', to: 'forbidden', scroll: false },
  uncheck: { target: 'required', value: 'forbidden', files: 'forbidden', to: 'forbidden', scroll: false },
  fill: { target: 'required', value: 'present', files: 'forbidden', to: 'forbidden', scroll: false },
  type: { target: 'required', value: 'nonempty', files: 'forbidden', to: 'forbidden', scroll: false },
  press: { target: 'required', value: 'nonempty', files: 'forbidden', to: 'forbidden', scroll: false },
  select: { target: 'required', value: 'nonempty', files: 'forbidden', to: 'forbidden', scroll: false },
  upload: { target: 'required', value: 'forbidden', files: 'required', to: 'forbidden', scroll: false },
  drag: { target: 'required', value: 'forbidden', files: 'forbidden', to: 'required', scroll: false },
  scroll: { target: 'optional', value: 'forbidden', files: 'forbidden', to: 'forbidden', scroll: true },
  back: { target: 'forbidden', value: 'forbidden', files: 'forbidden', to: 'forbidden', scroll: false },
  forward: { target: 'forbidden', value: 'forbidden', files: 'forbidden', to: 'forbidden', scroll: false },
  reload: { target: 'forbidden', value: 'forbidden', files: 'forbidden', to: 'forbidden', scroll: false },
};

const TARGET_HELP = 'Exactly one of {ref}, {selector}, {role, name?}, {name}, {label}, {text}, {testid}, or {x,y}. frame, within, and nth narrow a non-point locator.';

/** What the model can copy into the next call. Wire shape is error.details.expected. */
export function expectedAct(action: ActAction): Record<string, string> {
  const rule = ACTION_RULES[action];
  return {
    action,
    target: rule.target === 'forbidden' ? 'forbidden' : rule.target === 'optional' ? `optional. ${TARGET_HELP}` : `required. ${TARGET_HELP}`,
    value: rule.value === 'forbidden' ? 'forbidden' : rule.value === 'present' ? 'string, required; "" clears the field' : rule.value === 'optional' ? 'optional string' : 'non-empty string, required',
    files: rule.files === 'required' ? 'non-empty string[], required' : 'forbidden',
    to: rule.to === 'required' ? `required. ${TARGET_HELP}` : 'forbidden',
    direction: rule.scroll ? 'optional up|down|left|right (default down)' : 'forbidden',
    amount: rule.scroll ? 'optional number (default 600)' : 'forbidden',
    method: action === 'click' ? 'optional cdp|dom. dom runs HTMLElement.click() and sends no mouse event. Only after not_delivered or no box.' : 'forbidden',
  };
}

function reject(action: ActAction, message: string): never {
  throw new ActionError('invalid_args', message, 'Copy expected and send only those fields.', { details: { expected: expectedAct(action) } });
}

/** `name` only modifies `role`. Any other pair of these is two locators. */
function semanticKeys(t: RawTarget): string[] {
  const keys: string[] = [];
  if (t.role) keys.push('role');
  if (t.label) keys.push('label');
  if (t.text) keys.push('text');
  if (t.testid) keys.push('testid');
  if (t.name && !t.role) keys.push('name');
  return keys;
}

function families(t: RawTarget): string[] {
  const found: string[] = [];
  if (t.ref !== undefined && t.ref !== '') found.push('ref');
  if (t.selector) found.push('selector');
  if (t.x !== undefined || t.y !== undefined) found.push('{x,y}');
  const semantic = semanticKeys(t);
  if (semantic.length === 1) found.push(semantic[0]);
  else if (semantic.length > 1) found.push(semantic.join('+'));
  return found;
}

export function pickTarget(t: RawTarget | undefined, action: ActAction, slot: 'target' | 'to'): Target | undefined {
  if (!t) return undefined;
  const found = families(t);
  if ((t.x === undefined) !== (t.y === undefined)) reject(action, `${slot} point needs both x and y.`);
  if (semanticKeys(t).length > 1) reject(action, `${slot} mixes ${semanticKeys(t).join(' and ')}. name is only a modifier of role.`);
  if (found.includes('{x,y}') && (t.frame !== undefined || t.within || t.nth !== undefined)) reject(action, `${slot} point cannot take frame, within, or nth. Those are ignored and the click hits the top document.`);
  if (found.length > 1) reject(action, `${slot} mixes ${found.join(' and ')}. ${TARGET_HELP}`);
  if (found.length === 0) {
    if (t.frame !== undefined || t.within || t.nth !== undefined) reject(action, `${slot} has modifiers but no locator.`);
    return undefined;
  }
  const mods = { ...(t.frame !== undefined && { frame: t.frame }), ...(t.within && { within: t.within }) };
  if (t.ref !== undefined && t.ref !== '') return { ref: t.ref, ...mods };
  if (t.selector) return { selector: t.selector, ...(t.nth !== undefined && { nth: t.nth }), ...mods };
  if (t.x !== undefined && t.y !== undefined) return { x: t.x, y: t.y };
  return { role: t.role, name: t.name, label: t.label, text: t.text, testid: t.testid, ...(t.nth !== undefined && { nth: t.nth }), ...mods };
}

function present(value: unknown): boolean {
  return value !== undefined;
}

export function checkActInput(input: ActToolInput): { target?: Target; to?: Target; method?: 'cdp' | 'dom' } {
  validate(actionShape, input);
  const rule = ACTION_RULES[input.action];
  if (!Object.hasOwn(ACTION_RULES, input.action)) throw new ActionError('invalid_args', `Unknown action ${input.action}`, `Choose one of: ${Object.keys(ACTION_RULES).join(', ')}`);
  const target = pickTarget(input.target, input.action, 'target');
  const to = pickTarget(input.to, input.action, 'to');
  if (rule.target === 'required' && !target) reject(input.action, `action "${input.action}" needs a target.`);
  if (rule.target === 'forbidden' && target) reject(input.action, `action "${input.action}" does not take a target.`);
  if (rule.to === 'required' && !to) reject(input.action, `action "${input.action}" needs to.`);
  if (rule.to === 'forbidden' && to) reject(input.action, `action "${input.action}" does not take to.`);
  if (rule.value === 'present' && input.value === undefined) reject(input.action, `action "${input.action}" needs value. Pass "" to clear the field; omitting it would clear it by accident.`);
  if (rule.value === 'nonempty' && !input.value) reject(input.action, `action "${input.action}" needs a non-empty value. Omitting it is not a default key.`);
  if (rule.value === 'forbidden' && present(input.value)) reject(input.action, `action "${input.action}" does not take value.`);
  if (rule.files === 'required' && !(input.files && input.files.length)) reject(input.action, `action "${input.action}" needs files.`);
  if (rule.files === 'forbidden' && input.files !== undefined) reject(input.action, `action "${input.action}" does not take files.`);
  if (!rule.scroll && (input.direction !== undefined || input.amount !== undefined)) reject(input.action, `action "${input.action}" does not take direction or amount.`);
  if (input.method !== undefined) {
    if (input.method !== 'cdp' && input.method !== 'dom') reject(input.action, 'method must be "cdp" or "dom".');
    if (input.action !== 'click') reject(input.action, `action "${input.action}" does not take method.`);
    if (input.method === 'dom' && input.target && (input.target.x !== undefined || input.target.y !== undefined)) reject(input.action, 'method "dom" needs an element, not a point.');
  }
  return { target, to, ...(input.method && { method: input.method }) };
}

/** Validate the public contract before sending a compiled expectation to the page. */
export function checkExpect(what: Expectation): void {
  validate(expectationShape, what);
  const conditions = ['text', 'notText', 'url', 'title', 'visible', 'value', 'checked', 'selected', 'enabled'] as const;
  if (!what.target && !conditions.some(key => what[key] !== undefined)) throw new ActionError('invalid_args', 'expect needs a target or a condition.', 'Use a target to wait for visibility, or text/url/title for the document.');
  if (what.target) {
    const target = pickTarget(what.target, 'click', 'target');
    if (!target || 'x' in target) throw new ActionError('invalid_args', 'expect needs an element target, not a point.', 'Use find({x,y}) to obtain an element target.');
    if (what.url !== undefined || what.title !== undefined) throw new ActionError('invalid_args', 'Use separate expectations for an element and page URL/title.');
  } else if (['visible', 'value', 'checked', 'selected', 'enabled'].some(key => what[key as keyof Expectation] !== undefined)) {
    throw new ActionError('invalid_args', 'Control conditions require target.', 'Pass the same target used by read or act.');
  }
}

import { defaultSources, USER_ADAPTERS_DIR } from '../src/lib/sources.js';
import { describe, it, expect } from 'vitest';
import { Client, InMemoryTransport } from '@modelcontextprotocol/client';
import { Runtime } from '../src/runtime/runtime.js';
import { createMcpServer } from '../src/mcp/server.js';
import type { RuntimePage } from '../src/backends/page-types.js';

/** Parse the tool result's text content (the one result envelope: {ok,…} | {ok:false,error}). */
function body(r: { content?: Array<{ type: string; text?: string }> }): Record<string, unknown> {
  const t = (r.content ?? []).find((c) => c.type === 'text')?.text ?? '{}';
  try { return JSON.parse(t) as Record<string, unknown>; } catch { return { raw: t }; }
}

async function harness() {
  const rt = new Runtime({ sources: defaultSources(), userAdaptersDir: USER_ADAPTERS_DIR, log: () => {} });
  await rt.init();
  // Adapter execution always requires a browser page; this focused MCP test supplies one.
  rt.browserAvailable = () => true;
  rt.getAdapterPage = async () => ({}) as RuntimePage;
  rt.toolContext = async () => ({ tab: {}, sites: {}, recon: {} });
  const session = createMcpServer(rt, `test-${Math.random().toString(36).slice(2)}`);
  const [clientT, serverT] = InMemoryTransport.createLinkedPair();
  await session.server.connect(serverT);
  let elicits = 0;
  const client = new Client({ name: 'test', version: '0' }, { capabilities: { elicitation: {} } });
  client.setRequestHandler('elicitation/create', async () => { elicits += 1; throw new Error('Unexpected approval request'); });
  await client.connect(clientT);
  const site = `ctest${Math.random().toString(36).slice(2)}`;
  const drafts: string[] = [];
  const define = async (name: string, overrides: Record<string, unknown> = {}) => {
    const definition = { site, name, description: 'test write', access: 'write', func: 'async () => ({ done: true })', ...overrides };
    const result = await client.callTool({ name: 'js', arguments: { code: `await tools.define({...${JSON.stringify(definition)}, func: (${definition.func})})` } });
    const data: Record<string, unknown> = { ok: body(result).ok, ...(body(result).value as Record<string, unknown>) };
    if (typeof data.draftId === 'string') drafts.push(data.draftId);
    return { result, data };
  };
  const js = async (code: string) => { const result = body(await client.callTool({ name: 'js', arguments: { code } })); return result.ok ? { ok: true, ...(result.value as Record<string, unknown>) } : result; };
  const tryDraft = async (draftId: string, args: Record<string, unknown> = {}, expect: Record<string, unknown> = { path: 'value.done', equals: true }) => js(`await tools.try(${JSON.stringify(draftId)}, ${JSON.stringify(args)}, ${JSON.stringify(expect)})`);
  const activate = async (draftId: string) => js(`await tools.activate(${JSON.stringify(draftId)})`);
  const cleanup = async () => {
    for (const draftId of drafts) await js(`await tools.discard(${JSON.stringify(draftId)})`).catch(() => {});
    try { await client.callTool({ name: 'js', arguments: { code: `await tools.remove('${site}', 'poke')` } }); } catch { /* ignore */ }
    await client.close().catch(() => {}); await rt.shutdown().catch(() => {});
  };
  return { client, site, js, define, tryDraft, activate, elicits: () => elicits, cleanup };
}

describe('adapter draft lifecycle and write commands', () => {
  it('runs writes through site_run, typed tools, and js without elicitation', async () => {
    const h = await harness();
    try {
      const { data } = await h.define('poke', { args: [{ name: 'x', required: false }] });
      expect(data).toMatchObject({ ok: true, draftId: expect.any(String) });
      expect(body(await h.client.callTool({ name: 'site_run', arguments: { site: h.site, command: 'poke', args: {} } }))).toMatchObject({ ok: false, error: { code: 'unknown_command' } });
      expect((await h.client.listTools()).tools.some((t) => t.name === `${h.site}_poke`)).toBe(false);
      expect(await h.tryDraft(data.draftId as string)).toMatchObject({ ok: true, verification: { passed: true } });
      expect(await h.activate(data.draftId as string)).toMatchObject({ ok: true, site: h.site });
      expect(body(await h.client.callTool({ name: 'sites_search', arguments: {} }))).toMatchObject({ sites: expect.arrayContaining([expect.objectContaining({ site: h.site, commands: 1, write: 1 })]) });
      const direct = await h.client.callTool({ name: 'site_run', arguments: { site: h.site, command: 'poke', args: {} } });
      expect(body(direct)).toMatchObject({ ok: true, value: { done: true } });
      await h.client.callTool({ name: 'js', arguments: { code: `await sites.enable('${h.site}', { write: true })` } });
      const tools = await h.client.listTools();
      expect(tools.tools.some(t => t.name === `${h.site}_poke`)).toBe(true);
      const typed = await h.client.callTool({ name: `${h.site}_poke`, arguments: {} });
      expect(body(typed)).toMatchObject({ ok: true, value: { done: true } });
      const js = await h.client.callTool({ name: 'js', arguments: { code: `await sites.${h.site}.poke({})` } });
      expect(body(js)).toMatchObject({ ok: true, value: { done: true } });
      expect(h.elicits()).toBe(0);
    } finally { await h.cleanup(); }
  });

});

## API reference (generated from the public TypeScript declarations — do not edit)

In `js` the globals are `browser`, `agent`, `sites`, `recon`, `tools`, `session` and `nodeRepl`. Await API methods; returned Tab and Browser handles persist across calls. Use docs_get with name:"api-reference" and member:"Tab.act" (or another class/member) for a focused reference. Site adapter definitions are documented in `define-tools`.

```ts
interface AgentApi {
  agent: { browsers: { getDefault(): Promise<Browser>; }; browser: Browser; documentation: { get(name: string): Promise<string | null>; }; };
  sites: Record<string, unknown> & { search(q: string, limit?: number): Promise<unknown>; list(): Promise<unknown>; enable(site: string, opts?: { write?: boolean; }): Promise<{ site: string; tools: Array<string>; }>; disable(site: string): Promise<boolean>; run(site: string, name: string, args?: Record<string, unknown>): Promise<unknown>; };
  recon: {
    discover(tab: Tab, opts?: { maxScripts?: number; includeStatic?: boolean; includeAssets?: boolean; includeInline?: boolean; fetchTimeoutMs?: number; network?: Array<Record<string, unknown>>; }): Promise<DiscoverResult>;
  };
  tools: {
    define(def: ToolDefinition | (Omit<ToolDefinition, "func"> & { func?: string | ((ctx: Record<string, unknown>) => unknown); })): Promise<{ draftId: string; site: string; name: string; args: Array<Arg>; }>;
    try(draftId: string, args: Record<string, unknown>, expect: DraftExpectation): Promise<{ result: CommandRunResult | CommandRunError; verification: { passed: boolean; checks: Array<{ check: string; passed: boolean; actual?: unknown; }>; }; }>;
    activate(draftId: string): Promise<{ site: string; name: string; file: string; verifiedAt: string; }>;
    discard(draftId: string): Promise<{ draftId: string; discarded: true; }>;
    list(): Promise<Array<{ site: string; name: string; file: string; }>>;
    remove(site: string, name: string): Promise<boolean>;
  };
  session: { id: string; };
}

class Browser {
  id: string;
  type: "extension" | "electron";
  chrome: { // Chrome APIs through the connected backend. Electron supports an explicit compatibility subset.
    call(method: string, args?: Array<unknown>): Promise<unknown>;
    describe(member: string): Promise<unknown>;
    watch(event: string, options?: StreamOptions): Promise<EventStream>;
  };
  logs: { // This extension's own service-worker logs; not logs of other installed extensions.
    watch(options?: StreamOptions): Promise<EventStream>;
    read(options?: StreamReadOptions): Promise<StreamBatch>;
  };
  tabs: {
    new(url?: string): Promise<Tab>;
    list(): Promise<Array<{ id?: string; tabId: number; pending?: true; url?: string; title?: string; active: boolean; selected: boolean; origin: "agent" | "user"; state: "active" | "handoff"; }>>;
    get(tab: string | { tab?: string; tabId: number; }, opts?: { timeoutMs?: number; }): Promise<Tab>;
    selected(): Promise<Tab | undefined>;
    finalize(opts?: { keep?: Array<{ tab: string | Tab; status: "handoff" | "deliverable"; }>; }): Promise<{ closed: Array<string>; kept: Array<string>; failed: Array<{ page: string; reason: string; }>; }>;
  };
  user: {
    openTabs(options?: { query?: string; limit?: number; }): Promise<Array<UserTabInfo>>;
    claimTab(tab: { tabId?: number; active?: boolean; title?: string; url?: string; expectedUrl?: string; expectedTitle?: string; }): Promise<Tab>; // Claim by foreground, id, or unique url/title lookup; expected fields verify the tab's current identity.
    closeTabs(tabIds: Array<number>): Promise<CloseUserTabsResult>; // Close user tabs by Chrome id without claiming or loading their pages.
  };
  nameSession(name: string): Promise<void>;
  capabilities: {
    list(): Promise<Array<{ id: string; description: string; }>>;
    get(id: string): Promise<Record<string, unknown>>;
  };
  documentation(): Promise<string>;
}

class Tab {
  tabId?: number; // `id` is the Chrome tab id as a string; `tabId` is the numeric id when claimed from a user tab.
  id: string;
  goto(url: string, opts?: { waitUntil?: "load" | "none"; settleMs?: number; }): Promise<{ url: string | null; title: string | null; }>;
  url(): Promise<string | null>;
  title(): Promise<string | null>;
  back(): Promise<void>;
  forward(): Promise<void>;
  reload(): Promise<void>;
  close(): Promise<void>; // Close this tab, whether it was opened or claimed by this session.
  release(): Promise<void>; // Keep this tab open and give up this session's control of it.
  observe(opts?: ObserveOptions): Promise<ObserveResult>; // ARIA overview by default; format:'dom' reveals visible controls and live attributes. Observed refs automatically route to their frame.
  screenshot(opts?: { fullPage?: boolean; annotate?: boolean; format?: "png" | "jpeg"; quality?: number; }): Promise<ImageValue>;
  find(target: (Target & { limit?: number; }) | { query: string; limit?: number; frame?: FrameStep | Array<FrameStep>; }): Promise<FindResult | ElementAtResult | QueryFindResult>;
  read(opts: ReadElementOptions): Promise<ElementDetails>; // With target: exact current element text, attributes and live values, without scrolling. Otherwise: bounded document text scan (including open shadow roots), restores scroll; pass result.next to continue. A growing feed returns reason `unbounded`; the scan stops rather than chasing an endless bottom.
  read(opts?: ReadOptions): Promise<DocumentReadResult>; // With target: exact current element text, attributes and live values, without scrolling. Otherwise: bounded document text scan (including open shadow roots), restores scroll; pass result.next to continue. A growing feed returns reason `unbounded`; the scan stops rather than chasing an endless bottom.
  act(opts: ActOptions): Promise<ActionOutcome>; // wait + act in one call at the runtime edge: locate → wait actionable → hit-test → real input → settle. `method:'dom'` skips the mouse event.
  webmcp: { // WebMCP: tools the page itself registers via navigator.modelContext (page-provided tool source).
    list(options?: { name?: string; frame?: FrameStep | Array<FrameStep>; }): Promise<Array<PageTool>>; // List names/descriptions, or fetch one full schema by name. Scoped to the requested frame.
    call(name: string, input?: Record<string, unknown>, options?: { frame?: FrameStep | Array<FrameStep>; }): Promise<unknown>;
  };
  expect(what: Expectation, opts?: { timeoutMs?: number; }): Promise<CheckResult>; // Assert what the page must show now (polled up to timeoutMs).
  evaluate(script: string | ((arg: any) => any), opts?: { arg?: unknown; frame?: FrameStep | Array<FrameStep>; timeoutMs?: number; }): Promise<unknown>; // Main World page code; functions receive only opts.arg, never host closures. Dispatched scripts are never replayed.
  cdp: { // Native CDP on this Tab's shared debugger attachment. Parameters are not rewritten.
    send(method: string, params?: Record<string, unknown>, target?: { frameId: string; }): Promise<unknown>;
    watch(event: string, options?: StreamOptions): Promise<EventStream>;
  };
  dialog: { // Native alert/confirm/prompt dialogs block the page; commands fail with `dialog_open` until answered.
    get(): Promise<DialogInfo | null>;
    accept(text?: string): Promise<DialogInfo | null>;
    dismiss(): Promise<DialogInfo | null>;
  };
  console: { // Console messages and uncaught exceptions since the tab was attached (the plugin's tab.dev.logs); cursor-paged like network.read.
    read(opts?: StreamReadOptions): Promise<StreamBatch>;
    watch(options?: StreamOptions): Promise<EventStream>;
  };
  network: {
    start(pattern?: string): Promise<boolean>;
    list(opts?: { filter?: string; limit?: number; afterSequence?: number; }): Promise<{ cursor: number; entries: Array<Record<string, unknown>>; hasMore: boolean; }>;
    detail(opts: { seq?: number; requestId?: string; part?: "request" | "response"; start?: number; maxChars?: number; }): Promise<Record<string, unknown>>;
    read(opts?: { pattern?: string; limit?: number; includeStatic?: boolean; afterSequence?: number; }): Promise<{ cursor: number; entries: Array<unknown>; hasMore: boolean; }>; // Cursor-paged read: pass `afterSequence` from the previous result to get only new requests. Returns network rows only; endpoint candidates come from the explicit `recon.discover(tab)` (not a hidden side effect of reading).
  };
  cookies(domain: string): Promise<Array<unknown>>;
  cookie(name: string, opts?: { domain?: string; }): Promise<string | undefined>; // Read one cookie's value at run time — useful for per-request tokens an adapter needs (csrf/ct0/ csrftoken/XSRF-TOKEN). Defaults to the current page's host. Returns undefined when the cookie is absent.
  fetchJson(url: string, opts?: Record<string, unknown>): Promise<unknown>; // Fetch JSON through the page (its cookies and origin) after verifying the endpoint.
  frames(): Promise<Array<{ index: number; frameId: string; url: string; name: string; crossOrigin?: boolean; oopif?: boolean; }>>;
  download(download: { tab: string; afterSequence: number; started: Array<{ seq: number; guid?: string; url: string; suggestedFilename: string; }>; }, timeoutMs?: number): Promise<DownloadWaitResult>; // Wait for the page download begun after a tab.act cursor, then check Chrome's file state.
}

type Target = ({ frame?: FrameStep | FrameStep[]; within?: string }) & (
