/** Set up both connections: Chrome → local host, MCP client → local host. */
import { execFile, execFileSync, spawn } from 'node:child_process';
import { promisify } from 'node:util';
import { registerHost } from './registration.js';
import { doctor } from './doctor.js';
import { EXTENSION_STORE_URL } from './extension.js';
import { registerOpenCode } from './opencode.js';
import { registerPi } from './pi.js';
import { createInterface } from 'node:readline/promises';

const say = (line: string): void => { process.stdout.write(`${line}\n`); };
const exec = promisify(execFile);
type StdioCommand = { command: string; args: string[] };
type ClientRegistration = { name: string; status: 'existing' | 'registered' | 'failed' };

function which(cmd: string): string | null {
  try { return execFileSync(process.platform === 'win32' ? 'where' : 'which', [cmd], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'], timeout: 5000 }).split(/\r?\n/)[0].trim() || null; } catch { return null; }
}

const CLIENTS = [
  { name: 'Claude Code', bin: 'claude', scope: ['-s', 'user'] },
  { name: 'Codex', bin: 'codex', scope: [] },
  { name: 'OpenCode', bin: 'opencode', scope: [] },
  { name: 'Pi (pi-mcp-adapter required)', bin: 'pi', scope: [] },
];
async function selectClients(requested?: string[]): Promise<string[]> {
  const validate = (values: string[]): string[] => {
    const ids = [...new Set(values.map((value) => value.trim()))];
    if (!ids.length || ids.some((id) => !['claude', 'codex', 'opencode', 'pi', 'manual', 'none'].includes(id))) {
      throw new Error('Choose claude, codex, opencode, pi, manual, or none with --clients (comma-separated).');
    }
    if (ids.length > 1 && ids.some((id) => id === 'manual' || id === 'none')) {
      throw new Error('Choose manual or none on its own.');
    }
    for (const id of ids) {
      if (['claude', 'codex', 'opencode', 'pi'].includes(id) && !which(id)) throw new Error(`${id} CLI was not found on PATH. Install it first or choose manual.`);
    }
    return ids;
  };
  if (requested !== undefined) return validate(requested);
  if (!process.stdin.isTTY || !process.stdout.isTTY) {
    say('Non-interactive terminal: no MCP client settings will be changed. Use --clients claude,codex,opencode,pi to select clients, or --clients none to skip.');
    return ['manual'];
  }
  say('Choose which MCP clients to configure (only selected clients will be changed):');
  for (const client of CLIENTS) say(`  ${client.bin} — ${client.name}${which(client.bin) ? '' : ' (CLI not found; use manual)'}`);
  say('  manual — show configuration for Cursor, Claude Desktop, or another client');
  say('  none   — configure only the browser connection');
  const prompt = createInterface({ input: process.stdin, output: process.stdout });
  const controller = new AbortController();
  const cancel = (): void => controller.abort();
  prompt.on('SIGINT', cancel);
  prompt.on('close', cancel);
  try {
    while (true) {
      const answer = await prompt.question('Client IDs, separated by commas [manual]: ', { signal: controller.signal });
      try { return validate((answer.trim() || 'manual').split(',')); }
      catch (error) { say((error as Error).message); }
    }
  } catch { throw new Error('Setup cancelled; no configuration was changed.'); }
  finally { prompt.close(); }
}

function registerClients(c: StdioCommand, selected: string[]): ClientRegistration[] {
  const results: ClientRegistration[] = [];
  if (selected.includes('opencode')) {
    try { results.push({ name: 'OpenCode', status: registerOpenCode(c) }); }
    catch { results.push({ name: 'OpenCode', status: 'failed' }); }
  }
  if (selected.includes('pi')) {
    try { results.push({ name: 'Pi', status: registerPi(c) }); }
    catch { results.push({ name: 'Pi', status: 'failed' }); }
  }
  for (const client of CLIENTS.filter((client) => client.bin !== 'opencode' && client.bin !== 'pi' && selected.includes(client.bin))) {
    const bin = which(client.bin);
    if (!bin) { results.push({ name: client.name, status: 'failed' }); continue; }
    const options = { stdio: 'ignore' as const, timeout: 15_000 };
    let exists = false;
    try {
      execFileSync(bin, ['mcp', 'get', 'browsermcp'], options);
      exists = true;
    } catch { /* No readable registration; let add report any configuration error. */ }
    try {
      if (exists) execFileSync(bin, ['mcp', 'remove', ...client.scope, 'browsermcp'], options);
      execFileSync(bin, ['mcp', 'add', ...client.scope, 'browsermcp', '--', c.command, ...c.args], options);
      results.push({ name: client.name, status: 'registered' });
    } catch { results.push({ name: client.name, status: 'failed' }); }
  }
  return results;
}

async function openStorePage(): Promise<boolean> {
  try {
    if (process.platform === 'darwin') await exec('open', ['-a', 'Google Chrome', EXTENSION_STORE_URL], { timeout: 10_000 });
    else if (process.platform === 'win32') await exec('rundll32', ['url.dll,FileProtocolHandler', EXTENSION_STORE_URL], { timeout: 10_000 });
    else {
      // Browser processes may stay alive for the whole session; do not time out and kill them.
      return await new Promise<boolean>((resolve) => {
        const child = spawn(which('google-chrome') ?? which('chromium') ?? 'xdg-open', [EXTENSION_STORE_URL], { detached: true, stdio: 'ignore' });
        child.once('error', () => resolve(false));
        child.once('spawn', () => { child.unref(); resolve(true); });
      });
    }
    return true;
  } catch { return false; }
}

export async function setup(opts: { waitMs?: number; noOpen?: boolean; browsers?: string[]; userDataDirs?: string[]; clients?: string[] } = {}): Promise<boolean> {
  const waitMs = opts.waitMs ?? 180_000;
  if (!Number.isFinite(waitMs) || waitMs < 0) throw new Error('--wait must be a non-negative number of seconds.');

  const selected = await selectClients(opts.clients);
  const registration = registerHost({ browsers: opts.browsers, userDataDirs: opts.userDataDirs });
  const written = registration.manifests.filter((m) => m.written);
  if (!written.length) {
    say('No browser connection was registered. Check --browsers or --user-data-dir and run setup again.');
    return false;
  }
  say(`1/3  Browser connection registered: ${written.map((m) => m.browser).join(', ')}.`);

  // Absolute paths work in desktop clients even when their PATH differs from the terminal's.
  const command = { command: registration.launcher, args: ['stdio'] };
  const clients = registerClients(command, selected);
  say('2/3  MCP clients:');
  for (const client of clients) {
    const status = client.status === 'existing' ? 'already configured with this launcher' : client.status === 'registered' ? 'registered' : 'registration failed — use the configuration below';
    say(`     ${client.name}: ${status}.`);
  }
  if (selected.includes('none')) say('     Skipped; no MCP client settings were changed.');
  if (selected.includes('manual') || clients.some((client) => client.status === 'failed')) say(`     Manual configuration (Cursor, Claude Desktop, or other clients):\n${JSON.stringify({ mcpServers: { 'browsermcp': command } }, null, 2)}`);

  say('3/3  Checking the Chrome extension connection…');
  let status = await doctor();
  if (!status.ok) {
    const opened = !opts.noOpen && await openStorePage();
    say(`     ${opened ? 'Opened the Chrome Web Store. Install or enable BrowserMCP Connector in Chrome:' : 'Install or enable BrowserMCP Connector in Chrome:'} ${EXTENSION_STORE_URL}`);
    say('     Already installed? Keep Chrome open; the extension reconnects automatically.');
    if (waitMs > 0) say(`     Waiting up to ${waitMs / 1000} seconds for the browser connection…`);
    const until = Date.now() + waitMs;
    while (!status.ok && Date.now() < until) {
      await new Promise((resolve) => setTimeout(resolve, Math.min(2000, Math.max(0, until - Date.now()))));
      status = await doctor();
    }
  }
  if (!status.ok) {
    say('Browser is not connected yet. Your registration has been saved.');
    for (const advice of status.advice) say(`     ${advice}`);
    say('If the extension is already enabled, disable and re-enable it in chrome://extensions. Then run `browsermcp setup` again.');
    return false;
  }
  say('Browser connected.');
  if (clients.some((client) => client.status === 'failed')) {
    say('MCP client setup is incomplete. Apply the configuration above or fix the client CLI and rerun setup.');
    return false;
  }
  if (selected.includes('none')) say('Browser setup complete. MCP client settings were not changed.');
  else if (!clients.length) say('Next: add the configuration above to your MCP client, then reconnect it.');
  else say('Setup complete for the clients listed above. Restart or reconnect your MCP client to load the tools.');
  return true;
}

// browsermcp/adapter-sdk — the adapter contract (runtime). Pure: validate + return a descriptor, never register.

const ACCESS = new Set(['read', 'write']);

/** Validate an adapter descriptor and return it unchanged. No global state, no side effects. */
export function defineAdapter(descriptor) {
  const d = descriptor ?? {};
  if (typeof d.description !== 'string' || !d.description.trim()) throw new Error('adapter: `description` (non-empty string) is required');
  if (!ACCESS.has(d.access)) throw new Error("adapter: `access` must be 'read' or 'write'");
  if (typeof d.run !== 'function') throw new Error('adapter: `run` must be a function (ctx) => data');
  if (d.result !== undefined && (!['rows', 'value'].includes(d.result?.kind) || typeof d.result?.description !== 'string' || !d.result.description.trim() || d.result.fields !== undefined && (!d.result.fields || typeof d.result.fields !== 'object' || Object.values(d.result.fields).some((v) => typeof v !== 'string')) || d.result.paginated && d.result.kind !== 'rows')) throw new Error('adapter: `result` needs kind rows|value and a description; fields must be text and paginated applies to rows');
  if (d.args !== undefined) {
    if (!Array.isArray(d.args)) throw new Error('adapter: `args` must be an array');
    for (const a of d.args) if (!a || typeof a.name !== 'string' || !/^[a-z][a-z0-9_]*$/.test(a.name)) throw new Error(`adapter: arg name "${a?.name}" must be snake_case (agent-native)`);
  }
  return d;
}

/** A coded, agent-facing error an adapter can throw; the runtime surfaces { code, message, hint }. */
export class AdapterError extends Error {
  constructor(code, message, hint) { super(message); this.name = 'AdapterError'; this.code = code; this.hint = hint; }
}

/** Common coded failures, so adapters branch on one vocabulary. */
export const errors = {
  auth: (message = 'Not logged in', hint = 'Open the site and sign in, then retry.') => new AdapterError('auth_required', message, hint),
  empty: (message = 'No results') => new AdapterError('empty_result', message),
  argument: (message, hint) => new AdapterError('invalid_args', message, hint),
  upstream: (message, hint) => new AdapterError('upstream_error', message, hint),
};

// browsermcp/adapter-sdk — the adapter contract (types). This file is the source of truth for what an adapter may use.

export type Access = 'read' | 'write';

export interface ArgValue {
  type?: 'string' | 'int' | 'number' | 'boolean' | 'array' | 'object';
  nullable?: boolean;
  choices?: Array<string | number | boolean>;
  items?: ArgValue;
  properties?: Record<string, ArgValue & { required?: boolean; help?: string }>;
  min?: number;
  max?: number;
  minLength?: number;
  maxLength?: number;
  /** One representative value, shown to the agent; not used as a default. */
  example?: unknown;
}

export interface Arg extends ArgValue {
  /** snake_case, agent-native JSON key */
  name: string;
  required?: boolean;
  default?: unknown;
  /** one line, agent-facing, no CLI grammar */
  help?: string;
}

/** Cursor-paged network read (pass `afterSequence` from the previous result). */
export interface NetworkReadResult { cursor: number; entries: unknown[]; hasMore: boolean }

/**
 * The tab object model — the SAME surface an agent drives in the `js` tool. An adapter's `run` gets one bound to the
 * site's page. This interface is the adapter-visible subset; the core's Tab satisfies it structurally.
 */
export interface Tab {
  readonly id: string;
  goto(url: string, opts?: { waitUntil?: 'load' | 'none'; settleMs?: number }): Promise<{ url: string | null; title: string | null }>;
  url(): Promise<string | null>;
  reload(): Promise<void>;
  title(): Promise<string | null>;
  observe(opts?: Record<string, unknown>): Promise<Record<string, unknown>>;
  act(opts: Record<string, unknown>): Promise<Record<string, unknown>>;
  find(target: Record<string, unknown>): Promise<unknown>;
  expect(what: Record<string, unknown>, opts?: { timeoutMs?: number }): Promise<unknown>;
  evaluate(js: string | ((arg: any) => any), opts?: { arg?: unknown; frame?: number; timeoutMs?: number }): Promise<unknown>;
  /** Fetch JSON through the page (its cookies, its origin) — the network-first way to call a site's own API. */
  fetchJson(url: string, opts?: Record<string, unknown>): Promise<unknown>;
  /** Read one cookie's value at run time (e.g. a csrf token). */
  cookie(name: string, opts?: { domain?: string }): Promise<string | undefined>;
  cookies(domain: string): Promise<unknown[]>;
  screenshot(opts?: { fullPage?: boolean; annotate?: boolean; format?: 'png' | 'jpeg'; quality?: number }): Promise<unknown>;
  readonly network: {
    start(pattern?: string): Promise<boolean>;
    list(opts?: { filter?: string; limit?: number; afterSequence?: number }): Promise<{ cursor: number; entries: unknown[]; hasMore: boolean }>;
    detail(opts: { seq?: number; requestId?: string; part?: 'request' | 'response'; start?: number; maxChars?: number }): Promise<unknown>;
    read(opts?: { pattern?: string; limit?: number; includeStatic?: boolean; afterSequence?: number }): Promise<NetworkReadResult>;
  };
}

export interface Sites { [site: string]: Record<string, (args?: Record<string, unknown>) => Promise<unknown>> | unknown }
export interface Recon { discover(tab: Tab): Promise<unknown> }

/** What `run` receives. `tab` is the object model; `sites`/`recon` let an adapter reuse siblings + discovery. */
export interface AdapterContext {
  args: Record<string, unknown>;
  tab: Tab;
  sites: Sites;
  recon: Recon;
  signal?: AbortSignal;
}

export interface AdapterDescriptor {
  description: string;
  access: Access;
  /** Agent-facing result shape. `rows` may include nextCursor; `value` is one object/scalar. */
  result?: { kind: 'rows' | 'value'; description: string; fields?: Record<string, string>; paginated?: boolean };
  /** Site metadata and tool icon host; the adapter navigates explicitly when needed. */
  domain?: string;
  args?: Arg[];
  /** aliases resolve to this command */
  aliases?: string[];
  run(ctx: AdapterContext): Promise<unknown>;
}

/** Validate + return an adapter descriptor. Pure: no registration, no side effects. */
export function defineAdapter(descriptor: AdapterDescriptor): AdapterDescriptor;

export class AdapterError extends Error { code: string; hint?: string; constructor(code: string, message: string, hint?: string); }
export const errors: {
  auth(message?: string, hint?: string): AdapterError;
  empty(message?: string): AdapterError;
  argument(message: string, hint?: string): AdapterError;
  upstream(message: string, hint?: string): AdapterError;
};

/** What every object of the model carries: the runtime, the MCP session id, and that session's state. */
import type { Runtime, SessionState } from '../runtime/runtime.js';

export interface SessionContext { rt: Runtime; sessionId: string; state: SessionState }

/** Static MCP surface for a launcher that starts before the Chrome-owned host. */
import { Client, InMemoryTransport } from '@modelcontextprotocol/client';
import { Runtime } from '../runtime/runtime.js';
import { createMcpServer } from './server.js';

export async function localCatalog(version: string) {
  // Reuse the real registrations so offline discovery cannot drift from the host's schemas.
  // This runtime only describes tools; it never handles an agent request or owns browser state.
  const rt = new Runtime();
  const session = createMcpServer(rt, 'catalog', { version });
  const [clientTransport, serverTransport] = InMemoryTransport.createLinkedPair();
  const client = new Client({ name: 'browsermcp-catalog', version }, { capabilities: {} });
  try {
    await session.server.connect(serverTransport);
    await client.connect(clientTransport);
    return {
      tools: await client.listTools(),
      resources: await client.listResources(),
      resourceTemplates: await client.listResourceTemplates(),
      prompts: await client.listPrompts(),
    };
  } finally {
    await client.close().catch(() => {});
    await session.server.close().catch(() => {});
    await session.close();
  }
}

import { defineAdapter, errors } from '@jackwener/browsermcp/adapter-sdk';
import { parseProfileSearch, searchProfilesApi } from './_shared.js';

export default defineAdapter({
  description: 'Search Facebook people, groups, and pages through its logged-in GraphQL API.',
  access: 'read', domain: 'facebook.com',
  result: { kind: 'rows', description: 'Profiles with Facebook IDs and URLs', paginated: true },
  args: [
    { name: 'query', type: 'string', required: true, help: 'Name or keywords' },
    { name: 'type', type: 'string', default: 'people', choices: ['people', 'groups', 'pages'], help: 'Search category' },
    { name: 'limit', type: 'int', default: 10, min: 1, max: 20, help: 'Requested API page size; Facebook may return additional profiles' },
    { name: 'cursor', type: 'string', maxLength: 10000, help: 'nextCursor from a previous call' },
  ],
  async run({ tab, args }) {
    const limit = Number(args.limit ?? 10);
    if (!Number.isInteger(limit) || limit < 1 || limit > 20) throw errors.argument('limit must be between 1 and 20');
    const result = parseProfileSearch(await searchProfilesApi(tab, args.query, args.type || 'people', limit, args.cursor || null));
    return { rows: result.rows, ...(result.pageInfo?.has_next_page && result.pageInfo.end_cursor ? { nextCursor: result.pageInfo.end_cursor } : {}) };
  },
});

import { defineAdapter, errors } from '@jackwener/browsermcp/adapter-sdk';
import { accountNumber, gmailBatchView, parseBatchView } from './_shared.js';

export default defineAdapter({
  description: 'Search Gmail threads through Gmail’s batch-view JSON API.',
  access: 'read', domain: 'mail.google.com',
  result: { kind: 'rows', description: 'Matching threads' },
  args: [
    { name: 'query', type: 'string', required: true, help: 'Gmail search syntax, such as from:example.com is:unread' },
    { name: 'limit', type: 'int', default: 20, min: 1, max: 50, help: 'Maximum threads from the first API page' },
    { name: 'account', type: 'int', default: 0, min: 0, max: 20, help: 'Gmail account index' },
  ],
  async run({ tab, args }) {
    const query = String(args.query || '').trim();
    if (!query) throw errors.argument('query is required');
    const limit = Number(args.limit ?? 20);
    if (!Number.isInteger(limit) || limit < 1 || limit > 50) throw errors.argument('limit must be between 1 and 50');
    const rows = parseBatchView(await gmailBatchView(tab, query, accountNumber(args.account)));
    return { rows: rows.slice(0, limit) };
  },
});

/**
 * The object model — the single surface behind both the typed MCP tools and the `js` session.
 *   agent.browsers → browser.tabs / browser.user / browser.capabilities → tab.observe / tab.act / …
 *   sites.<site>.<command>(args) · recon.discover(tab) · tools.define · browser.nameSession / browser.tabs.finalize
 * Split by object: tab.ts, browser.ts, api.ts (context.ts carries what they share). This file re-exports them.
 */
export * from './tab.js';
export * from './browser.js';
export * from './api.js';
export * from './context.js';

/** Stable, branchable errors for the object API and typed tools. */
export class ActionError extends Error {
  constructor(readonly code: string, message: string, readonly hint?: string, readonly data?: Record<string, unknown>) {
    super(message);
    this.name = 'ActionError';
  }
  toJSON(): Record<string, unknown> { return { code: this.code, message: this.message, ...(this.hint && { hint: this.hint }), ...this.data }; }
}

export function errorEnvelope(err: unknown): { ok: false; error: Record<string, unknown> } {
  if (err instanceof ActionError) {
    return { ok: false, error: err.toJSON() };
  }
  const e = (err ?? {}) as { code?: string; message?: string; hint?: string; name?: string; data?: unknown };
  const data = e.data && typeof e.data === 'object' && !Array.isArray(e.data) ? e.data as Record<string, unknown> : {};
  const raw = e.code ?? (e.name === 'BrowserCommandError' ? 'browser_command_failed' : 'error');
  return { ok: false, error: { code: raw, message: e.message ?? String(err), ...(e.hint && { hint: e.hint }), ...data } };
}

import { defineAdapter } from '@jackwener/browsermcp/adapter-sdk';
import { ensureOnBili, biliApiSigned, stripHtml } from './_shared.js';

export default defineAdapter({
  description: 'Search Bilibili for videos or users by keyword.',
  access: 'read',
  domain: 'bilibili.com',
  args: [
    { name: 'query', type: 'string', required: true, help: 'Search keyword' },
    { name: 'type', type: 'string', default: 'video', choices: ['video', 'user'], help: 'What to search for' },
    { name: 'page', type: 'int', default: 1, help: 'Result page number' },
    { name: 'limit', type: 'int', default: 20, help: 'How many results to return' },
  ],
  async run({ tab, args }) {
    await ensureOnBili(tab);
    const searchType = args.type === 'user' ? 'bili_user' : 'video';
    const data = await biliApiSigned(tab, '/x/web-interface/wbi/search/type', {
      search_type: searchType, keyword: args.query, page: Number(args.page) || 1,
    });
    const results = data?.result ?? [];
    const rows = results.slice(0, Number(args.limit) || 20).map((item, i) => {
      if (searchType === 'bili_user') {
        return {
          rank: i + 1, name: stripHtml(item.uname ?? ''), sign: (item.usign ?? '').trim(),
          fans: item.fans ?? 0, mid: item.mid ?? '',
          url: item.mid ? `https://space.bilibili.com/${item.mid}` : '',
        };
      }
      return {
        rank: i + 1, title: stripHtml(item.title ?? ''), author: item.author ?? '',
        plays: item.play ?? 0, bvid: item.bvid ?? '',
        url: item.bvid ? `https://www.bilibili.com/video/${item.bvid}` : '',
      };
    });
    return rows;
  },
});

/** Bounded, two-stage network evidence for agents. Raw captures stay in the session log. */
export interface NetworkEntry extends Record<string, unknown> { seq: number }

export function networkSummary(e: NetworkEntry): Record<string, unknown> {
  return {
    seq: e.seq,
    requestId: e.requestId,
    url: e.url ?? e.name,
    method: e.method ?? 'GET',
    status: e.responseStatus ?? e.status,
    contentType: e.responseContentType ?? e.contentType ?? e.mimeType,
    resourceType: e.resourceType,
    timestamp: e.timestamp ?? e.startTime ?? e.ts,
    completed: e.done ?? true,
    requestBytes: e.requestBodyFullSize,
    responseBytes: e.responseBodyFullSize,
    responseTruncated: e.responseBodyTruncated ?? false,
    requestTruncated: e.requestBodyTruncated ?? false,
  };
}

export function networkDetail(e: NetworkEntry, opts: { part?: 'request' | 'response'; start?: number; maxChars?: number } = {}): Record<string, unknown> {
  const part = opts.part ?? 'response';
  const raw = String(part === 'request' ? e.requestBodyPreview ?? '' : e.responsePreview ?? '');
  const fullSize = Number(part === 'request' ? e.requestBodyFullSize ?? raw.length : e.responseBodyFullSize ?? raw.length);
  const start = Math.min(Math.max(0, opts.start ?? 0), raw.length);
  const maxChars = Math.min(Math.max(200, opts.maxChars ?? 8_000), 100_000);
  const nextStart = start + maxChars < raw.length ? start + maxChars : undefined;
  return {
    ...networkSummary(e),
    requestHeaders: e.requestHeaders ?? {},
    responseHeaders: e.responseHeaders ?? {},
    body: { part, text: raw.slice(start, start + maxChars), start, ...(nextStart !== undefined && { nextStart }), fullSize,
      captureTruncated: part === 'request' ? e.requestBodyTruncated ?? false : e.responseBodyTruncated ?? false },
  };
}

import { defineAdapter, errors } from '@jackwener/browsermcp/adapter-sdk';
import { ensureOnReddit, postRows, assertListing } from './_shared.js';

export default defineAdapter({
  description: 'Search Reddit posts (optionally within a subreddit).',
  access: 'read',
  domain: 'reddit.com',
  args: [
    { name: 'query', type: 'string', required: true, help: 'Search text' },
    { name: 'subreddit', type: 'string', help: 'Restrict to this subreddit (without r/)' },
    { name: 'sort', type: 'string', default: 'relevance', choices: ['relevance', 'hot', 'top', 'new', 'comments'], help: 'Result sort' },
    { name: 'limit', type: 'int', default: 25, help: 'How many results to return' },
    { name: 'cursor', type: 'string', help: 'nextCursor (fullname) from a previous call' },
  ],
  async run({ tab, args }) {
    const query = String(args.query || '').trim();
    if (!query) throw errors.argument('`query` is required', 'Give search text, e.g. { query: "mechanical keyboards" }');
    await ensureOnReddit(tab);
    const sub = String(args.subreddit || '').replace(/^\/?r\//, '').trim();
    const sort = ['relevance', 'hot', 'top', 'new', 'comments'].includes(args.sort) ? args.sort : 'relevance';
    const limit = Math.min(Math.max(1, Number(args.limit) || 25), 100);
    const base = sub ? `https://www.reddit.com/r/${encodeURIComponent(sub)}/search.json` : `https://www.reddit.com/search.json`;
    const restrict = sub ? '&restrict_sr=1' : '';
    const after = args.cursor ? `&after=${encodeURIComponent(String(args.cursor))}` : '';
    const json = await tab.fetchJson(`${base}?q=${encodeURIComponent(query)}&sort=${sort}&limit=${limit}${restrict}${after}&raw_json=1`);
    assertListing(json);
    const rows = postRows(json);
    if (!rows.length) throw errors.empty(`No results for "${query}"`);
    return { rows, ...(json.data?.after && { nextCursor: json.data.after }) };
  },
});

import { defineAdapter, errors } from '@jackwener/browsermcp/adapter-sdk';
import { channelId, count, discordClient, guildId, messageRow } from './_shared.js';

export default defineAdapter({
  description: 'Search Discord server messages through the guild search API.',
  access: 'read', domain: 'discord.com',
  result: { kind: 'rows', description: 'Matching messages', paginated: true },
  args: [
    { name: 'query', type: 'string', required: true, help: 'Text to search' },
    { name: 'guild', type: 'string', help: 'Server ID or name; defaults to current server' },
    { name: 'channel', type: 'string', help: 'Optional channel ID or name' },
    { name: 'offset', type: 'int', default: 0, min: 0, help: 'Result offset from a previous call' },
  ],
  async run({ tab, args }) {
    const query = String(args.query || '').trim();
    if (!query) throw errors.argument('query is required');
    const offset = args.offset === undefined ? 0 : Number(args.offset);
    if (!Number.isInteger(offset) || offset < 0) throw errors.argument('offset must be a non-negative integer');
    const { api, route } = await discordClient(tab);
    const guild = await guildId(api, args.guild, route);
    const channel = args.channel ? (await channelId(api, { guild, channel: args.channel }, route)).channel : null;
    const path = `/guilds/${guild}/messages/search?content=${encodeURIComponent(query)}&sort_by=timestamp&sort_order=desc&offset=${offset}${channel ? `&channel_id=${channel}` : ''}`;
    const result = await api(path);
    if (!Array.isArray(result?.messages)) throw errors.upstream('Discord search API changed shape');
    const rows = result.messages.flatMap((group) => Array.isArray(group) ? group : []).map(messageRow);
    return { rows, total: Number(result.total_results || 0), ...(offset + rows.length < Number(result.total_results || 0) && rows.length ? { nextCursor: offset + rows.length } : {}) };
  },
});

import { createHash } from 'node:crypto';
import type { RuntimePage } from '../backends/page-types.js';
import type { FrameStep } from '../protocol.js';

export interface PageTool { name: string; description?: string; inputSchema?: unknown }
export interface PageToolsUpdate { status: 'ready' | 'unavailable'; frame: FrameStep[]; tools: Array<{ name: string; description?: string }>; truncated?: boolean }

/** Discovery is read-only and bounded. Full schemas are returned only on explicit lookup. */
export async function pageTools(page: RuntimePage, frame: FrameStep[] = []): Promise<PageTool[]> {
  const script = `(async () => {
    const mc = navigator.modelContext || document.modelContext;
    const source = navigator.modelContextTesting?.listTools ? navigator.modelContextTesting : mc;
    const list = source?.listTools || source?.getTools;
    if (!list) return [];
    const tools = await list.call(source);
    return (tools || []).map(t => ({name:t.name, description:t.description, inputSchema:t.inputSchema}));
  })()`;
  const value = frame.length ? await page.evaluateInFrame(script, frame, 1000) : await page.evaluate(script, {timeoutMs:1000});
  return Array.isArray(value) ? value.filter(t => t && typeof t.name === 'string') : [];
}

export async function pageToolsUpdate(page: RuntimePage, cache: Map<string, string>, key: string, frame: FrameStep[]): Promise<PageToolsUpdate | undefined> {
  try {
    const catalog = await pageTools(page, frame);
    const fingerprint = createHash('sha256').update(JSON.stringify(catalog)).digest('hex');
    const previous = cache.get(key);
    cache.set(key, fingerprint);
    if (previous === fingerprint || (previous === undefined && !catalog.length)) return;
    const tools: PageToolsUpdate['tools'] = [];
    let truncated = false;
    for (const tool of catalog) {
      const summary = {name:tool.name, ...(tool.description && {description:tool.description.slice(0,160)})};
      if (tools.length >= 12 || JSON.stringify([...tools,summary]).length > 2000) { truncated = true; continue; }
      if ((tool.description?.length ?? 0) > 160) truncated = true;
      tools.push(summary);
    }
    return {status:'ready', frame, tools, ...(truncated && {truncated})};
  } catch {
    const previous = cache.get(key);
    cache.set(key, 'unavailable');
    return previous === 'unavailable' ? undefined : {status:'unavailable', frame, tools:[]};
  }
}
